`timescale 1ns/1ps
`default_nettype none

// CPU-level self-checking testbench: cpu_core + imem + dmem.
// Test programs and their expected final state come from cpu_tests.hex,
// generated by TP3/py/gen_vectors.py (run by sim/prebuild.bat): every
// program in TP3/asm, short edge-case programs and random programs, each run
// on the Python ISS (TP3/py/iss.py) to get the expected registers, data
// memory, final PC, cycle count and halt reason.
//
// For each test, the way the Debug Unit will do it:
//   1. hold the core in reset, write the program into imem through the write
//      port and clear dmem through port A (as system_top will);
//   2. release reset with en = 1 and run until halted (watchdog: MAX_CYCLES
//      + 100 cycles);
//   3. compare halt_reason, cycle_cnt, PC, an empty pipeline, x0..x31 (debug
//      port), every dmem word (port B) and the dmem high-water mark.
// Checked every cycle:
//   - a pipeline register with valid = 0 has every control bit 0;
//   - a load is never in MEM while the instruction in EX reads its rd (the
//     load-use stall must prevent it);
//   - halting and halted are never both 1.
// The previous program stays in imem beyond the new one: OOR must stop the
// core before it runs into it.

module tb_cpu_core;

  localparam integer CLK_PERIOD  = 10;
  localparam integer IMEM_ADDR_W = 10;
  localparam integer DMEM_ADDR_W = 10;
  localparam integer IMEM_DEPTH  = 1 << IMEM_ADDR_W;
  localparam integer DMEM_DEPTH  = 1 << DMEM_ADDR_W;
  localparam integer MAX_CYCLES  = 3000;      // = CPU_MAX_CYCLES in gen_vectors.py
  localparam integer MAX_WORDS   = 1 << 17;   // = CPU_MAX_WORDS in gen_vectors.py
  localparam [31:0]  MAGIC       = 32'hC0DE0001;

  reg clk = 1'b0;
  always #(CLK_PERIOD/2) clk = ~clk;

  // ---------------- DUT and memories ----------------
  reg                    rst = 1'b1;
  reg                    en  = 1'b0;
  reg  [IMEM_ADDR_W:0]   imem_limit = 0;

  wire [IMEM_ADDR_W-1:0] imem_raddr;
  wire [31:0]            imem_rdata;
  reg                    imem_we = 1'b0;
  reg  [IMEM_ADDR_W-1:0] imem_waddr = 0;
  reg  [31:0]            imem_wdata = 32'd0;

  wire                   core_dmem_en;
  wire [3:0]             core_dmem_we;
  wire [DMEM_ADDR_W-1:0] core_dmem_addr;
  wire [31:0]            core_dmem_wdata;
  wire [31:0]            dmem_a_rdata, dmem_b_rdata;
  reg                    clr = 1'b0;
  reg  [DMEM_ADDR_W-1:0] clr_addr = 0;
  reg  [DMEM_ADDR_W-1:0] b_addr = 0;

  wire                   halting, halted;
  wire [2:0]             halt_reason;
  wire [31:0]            cycle_cnt;
  reg  [4:0]             dbg_reg_addr = 5'd0;
  wire [31:0]            dbg_reg_data;
  wire [511:0]           vec;

  imem #(.ADDR_W(IMEM_ADDR_W)) u_imem (
    .clk(clk), .we(imem_we), .waddr(imem_waddr), .wdata(imem_wdata),
    .raddr(imem_raddr), .rdata(imem_rdata)
  );

  // Port A: the core, or the clear sweep while the core is in reset
  dmem #(.ADDR_W(DMEM_ADDR_W)) u_dmem (
    .clk(clk),
    .a_en(clr ? 1'b1 : core_dmem_en),
    .a_we(clr ? 4'b1111 : core_dmem_we),
    .a_addr(clr ? clr_addr : core_dmem_addr),
    .a_wdata(clr ? 32'd0 : core_dmem_wdata),
    .a_rdata(dmem_a_rdata),
    .b_addr(b_addr), .b_rdata(dmem_b_rdata)
  );

  cpu_core #(
    .IMEM_ADDR_W(IMEM_ADDR_W), .DMEM_ADDR_W(DMEM_ADDR_W), .MAX_CYCLES(MAX_CYCLES)
  ) dut (
    .clk(clk), .rst(rst), .en(en), .imem_limit(imem_limit),
    .imem_addr(imem_raddr), .imem_rdata(imem_rdata),
    .dmem_en(core_dmem_en), .dmem_we(core_dmem_we), .dmem_addr(core_dmem_addr),
    .dmem_wdata(core_dmem_wdata), .dmem_rdata(dmem_a_rdata),
    .halting(halting), .halted(halted), .halt_reason(halt_reason),
    .cycle_cnt(cycle_cnt),
    .dbg_reg_addr(dbg_reg_addr), .dbg_reg_data(dbg_reg_data), .dbg_core_vec(vec)
  );

  // Pipeline fields from the debug vector (docs/protocol.md 6.2)
  wire [31:0] pc_if      = vec[31:0];
  wire [31:0] if_id_ctrl = vec[127:96];
  wire [31:0] id_ex_ctrl = vec[287:256];
  wire [31:0] ex_mem_ctrl = vec[415:384];
  wire [31:0] mem_wb_ctrl = vec[511:480];

  // ---------------- Test stream ----------------
  reg [31:0] stream [0:MAX_WORDS-1];
  integer p;  // read pointer into stream

  task get;
    output [31:0] w;
    begin
      w = stream[p];
      p = p + 1;
    end
  endtask

  reg [127:0] name;
  reg [31:0]  w0, w1, w2, w3;
  integer n_tests, t, i, prog_len, ran;
  reg [31:0] exp_pc, exp_cycles, exp_reason, exp_used, exp_word;
  reg [31:0] exp_regs [0:31];

  integer errors = 0;
  integer checks = 0;
  integer test_errors;

  task expect32;
    input [8*16-1:0] what;
    input [31:0]     got, exp;
    begin
      checks = checks + 1;
      if (got !== exp) begin
        errors = errors + 1;
        test_errors = test_errors + 1;
        $display("FAIL %0s: %0s expected=%08h got=%08h  TEST FAILED", name, what, exp, got);
      end
    end
  endtask

  // ---------------- Per-cycle invariants ----------------
  reg running = 1'b0;
  integer hwm;  // dmem high-water mark seen on the core's port A

  // Trace for TP3/py/test_hints_rtl.py: per cycle (first TRACE_CYCLES of
  // each program) the debug vector and the hazard decisions the core takes
  // on the next edge, to check the host CLI's "next cycle" hints.
  localparam integer TRACE_CYCLES = 300;
  integer trace_fd;

  always @(posedge clk) begin
    if (running && cycle_cnt < TRACE_CYCLES)
      $fdisplay(trace_fd, "C %h %b %b %b %b %b %b %h %b %h %b",
                vec, halting, halted, dut.fwd_a, dut.fwd_b, dut.load_use,
                dut.ex_redirect, dut.ex_target, dut.id_jal, dut.id_jal_target,
                dut.halt_accept);
  end

  always @(posedge clk) begin
    if (running) begin
      if (core_dmem_we != 4'b0000 && core_dmem_addr + 1 > hwm)
        hwm = core_dmem_addr + 1;
      if ((!id_ex_ctrl[30] && id_ex_ctrl != 32'd0) ||
          (!ex_mem_ctrl[12] && ex_mem_ctrl != 32'd0) ||
          (!mem_wb_ctrl[8] && mem_wb_ctrl != 32'd0) ||
          (!if_id_ctrl[0] && if_id_ctrl != 32'd0)) begin
        errors = errors + 1; test_errors = test_errors + 1;
        $display("FAIL %0s: bubble with control bits set at cycle %0d (ifid=%h idex=%h exmem=%h memwb=%h)  TEST FAILED",
                 name, cycle_cnt, if_id_ctrl, id_ex_ctrl, ex_mem_ctrl, mem_wb_ctrl);
      end
      if (ex_mem_ctrl[6] && ex_mem_ctrl[4:0] != 5'd0 &&
          (ex_mem_ctrl[4:0] == id_ex_ctrl[4:0] || ex_mem_ctrl[4:0] == id_ex_ctrl[9:5])) begin
        errors = errors + 1; test_errors = test_errors + 1;
        $display("FAIL %0s: load in MEM feeds EX (missing load-use stall) at cycle %0d  TEST FAILED",
                 name, cycle_cnt);
      end
      if (halting && halted) begin
        errors = errors + 1; test_errors = test_errors + 1;
        $display("FAIL %0s: halting and halted both set  TEST FAILED", name);
      end
    end
  end

  // ---------------- Main ----------------
  initial begin
    trace_fd = $fopen("core_trace.txt", "w");
    $readmemh("cpu_tests.hex", stream);
    p = 0;
    get(w0);
    if (w0 !== MAGIC) begin
      $display("FAIL: cpu_tests.hex missing or bad magic  TEST FAILED");
      $fatal(1, "no test vectors");
    end
    get(w0); n_tests = w0;
    get(w0);
    if (w0 != MAX_CYCLES)
      $fatal(1, "cpu_tests.hex was generated for another MAX_CYCLES");

    for (t = 0; t < n_tests; t = t + 1) begin
      test_errors = 0;
      get(w0); get(w1); get(w2); get(w3);
      name = {w0, w1, w2, w3};
      get(w0); prog_len = w0;
      $fdisplay(trace_fd, "T %0s", name);

      // 1. Reset, load the program, clear dmem
      @(negedge clk);
      rst = 1'b1; en = 1'b0; running = 1'b0;
      clr = 1'b1;
      for (i = 0; i < DMEM_DEPTH; i = i + 1) begin
        clr_addr = i;
        imem_we = (i < prog_len);
        imem_waddr = i;
        if (i < prog_len) get(imem_wdata);
        @(negedge clk);
      end
      clr = 1'b0; imem_we = 1'b0;
      imem_limit = prog_len;
      @(negedge clk);
      @(negedge clk);   // >= 2 cycles of reset after the last imem write

      // 2. Run
      hwm = 0;
      rst = 1'b0; en = 1'b1; running = 1'b1;
      ran = 0;
      while (!halted && ran < MAX_CYCLES + 100) begin
        @(negedge clk);
        ran = ran + 1;
      end
      en = 1'b0;
      @(negedge clk);
      running = 1'b0;

      // 3. Compare with the ISS
      get(exp_pc);
      get(exp_cycles);
      get(exp_reason);
      get(exp_used);
      for (i = 0; i < 32; i = i + 1) get(exp_regs[i]);

      expect32("halted", {31'd0, halted}, 32'd1);
      expect32("halt_reason", {29'd0, halt_reason}, exp_reason);
      expect32("cycles", cycle_cnt, exp_cycles);
      expect32("pc", pc_if, exp_pc);
      expect32("if_id empty", if_id_ctrl, 32'd0);
      expect32("id_ex empty", id_ex_ctrl, 32'd0);
      expect32("ex_mem empty", ex_mem_ctrl, 32'd0);
      expect32("mem_wb empty", mem_wb_ctrl, 32'd0);
      expect32("dmem_used", hwm, exp_used);
      for (i = 0; i < 32; i = i + 1) begin
        dbg_reg_addr = i;
        #1;
        expect32("register", dbg_reg_data, exp_regs[i]);
        if (dbg_reg_data !== exp_regs[i]) $display("     (x%0d)", i);
      end
      for (i = 0; i < DMEM_DEPTH; i = i + 1) begin
        exp_word = 32'd0;
        if (i < exp_used) get(exp_word);
        b_addr = i;
        @(negedge clk);
        expect32("dmem word", dmem_b_rdata, exp_word);
        if (dmem_b_rdata !== exp_word) $display("     (word %0d)", i);
      end

      if (test_errors == 0)
        $display("PASS %0s: reason=%0d pc=%08h cycles=%0d dmem_used=%0d",
                 name, halt_reason, pc_if, cycle_cnt, hwm);
    end

    $fclose(trace_fd);
    if (errors == 0)
      $display("ALL TESTS PASSED (%0d programs, %0d checks)", n_tests, checks);
    else
      $fatal(1, "%0d of %0d checks failed", errors, checks);
    $finish;
  end

endmodule

`default_nettype wire
